(7014038, 1060944, 52549, '<td valign="top">Totally amazing image. Outstanding work, Christophe. Congrats!</td>', 'Totally amazing image. Outstanding work, Christophe. Congrats!', '2013-04-05 05:08:23.000000', NULL, 0),
(7014039, 1060944, 109387, '<td valign="top">A lot of people out there sir! You had to wait a lot to get a good sky but in the end you found an amazing one and it fits perfectly the image. Your ideas will never end :)</td>', 'A lot of people out there sir! You had to wait a lot to get a good sky but in the end you found an amazing one and it fits perfectly the image. Your ideas will never end :)', '2013-04-05 05:22:54.000000', NULL, 0),
(7014041, 1060701, 31409, '<td valign="top">Yeah Doc!</td>', 'Yeah Doc!', '2013-04-05 05:48:42.000000', NULL, 0),
(7014042, 1060944, 63812, '<td valign="top">congrats!</td>', 'congrats!', '2013-04-05 06:00:19.000000', NULL, 0),
(7014043, 1060501, 63812, '<td valign="top">congrats! very deserved ribbon!</td>', 'congrats! very deserved ribbon!', '2013-04-05 06:01:11.000000', NULL, 0),
(7014047, 1060701, 114969, '<td valign="top">It reminds me the Easter eggs my mother used to cook when I was young: she wasn''t using tea, but onion skins in boiling water, with similar results. Ok, now I''m hungry ;) Congratulations on your ribbon, I am glad your hard work paid off!</td>', 'It reminds me the Easter eggs my mother used to cook when I was young: she wasn''t using tea, but onion skins in boiling water, with similar results. Ok, now I''m hungry ;) Congratulations on your ribbon, I am glad your hard work paid off!', '2013-04-05 06:39:57.000000', NULL, 0),
(7014048, 1060501, 114969, '<td valign="top">I showed your image to several coworkers: each of them instantly started to laugh :) This says it all! Congratulations on your ribbon, and to your (very) patient dog :)</td>', 'I showed your image to several coworkers: each of them instantly started to laugh :) This says it all! Congratulations on your ribbon, and to your (very) patient dog :)', '2013-04-05 06:41:18.000000', NULL, 0),
(7014050, 1060929, 114969, '<td valign="top">Very well done, I love the reflections at the base of the egg. Congratulations on the nice finish.</td>', 'Very well done, I love the reflections at the base of the egg. Congratulations on the nice finish.', '2013-04-05 07:00:39.000000', NULL, 0),
(7014051, 1060766, 114969, '<td valign="top">I really love when unbridled creativity, is rewarded. Congratulations Monica on your nice finish, can''t wait to see your next creation!</td>', 'I really love when unbridled creativity, is rewarded. Congratulations Monica on your nice finish, can''t wait to see your next creation!', '2013-04-05 07:04:03.000000', NULL, 0),
(7014052, 1060972, 114969, '<td valign="top">I agree, this should have finished much much higher than that. The transparent egg is fabulous. I love how you are able to combine extreme creativity and technical aspects Samantha, very inspiring!</td>', 'I agree, this should have finished much much higher than that. The transparent egg is fabulous. I love how you are able to combine extreme creativity and technical aspects Samantha, very inspiring!', '2013-04-05 07:06:31.000000', NULL, 0),
(7014053, 1060967, 114969, '<td valign="top">You really have your own style and particular ideas, Alessandro. Very intriguing and interesting concept: I also believe it should have finished higher than that. Anyway, DPC score isn''t always that meaningful. Now this image exists, and you are its author: I''m sure it makes you proud :)</td>', 'You really have your own style and particular ideas, Alessandro. Very intriguing and interesting concept: I also believe it should have finished higher than that. Anyway, DPC score isn''t always that meaningful. Now this image exists, and you are its author: I''m sure it makes you proud :)', '2013-04-05 07:10:07.000000', NULL, 0),
(7014054, 1060967, 109387, '<td valign="top"><table align="center" width="95%"><tr><td><div class="textsm"><b>Originally posted by gyaban:</b></div><hr/><i>Now this image exists, and you are its author: I''m sure it makes you proud :) </i></td></tr></table> <br/> <br/>Yes, it does, and that''s what it really matters :)<br/> <br/>Thanks to you and to all the people who left a message here!</td>', 'Originally posted by gyaban:Now this image exists, and you are its author: I''m sure it makes you proud :)   Yes, it does, and that''s what it really matters :) Thanks to you and to all the people who left a message here!', '2013-04-05 07:15:35.000000', NULL, 0),
(7014056, 1060043, 114969, '<td valign="top">It''s always a joy to discover your creations John. I just love how you don''t care about conformity, and goes your own way whatsoever. This one is fantastic, creepy as hell, definitely perfect for Easter.</td>', 'It''s always a joy to discover your creations John. I just love how you don''t care about conformity, and goes your own way whatsoever. This one is fantastic, creepy as hell, definitely perfect for Easter.', '2013-04-05 07:28:08.000000', NULL, 0),
